questionvariables.text:
/* Pools of rows: [id, expression (LaTeX string), correct category, explanation]. */
poolA: [
 ["A1", "\\(2k - 1\\)", allodd, "\\(2k - 1 = 2(k - 1) + 1\\) is always odd, and every odd number \\(n\\) is a value: take \\(k = \\dfrac{n + 1}{2}\\), which is an integer."],
 ["A2", "\\(2k + 5\\)", allodd, "\\(2k + 5 = 2(k + 2) + 1\\) is always odd, and every odd number \\(n\\) is a value: take \\(k = \\dfrac{n - 5}{2}\\), which is an integer."],
 ["A3", "\\(1 - 2k\\)", allodd, "\\(1 - 2k = 2(-k) + 1\\) is always odd, and as \\(k\\) runs through all the integers so does \\(-k\\), so every odd number appears."],
 ["A4", "\\(2k - 3\\)", allodd, "\\(2k - 3 = 2(k - 2) + 1\\) is always odd, and every odd number \\(n\\) is a value: take \\(k = \\dfrac{n + 3}{2}\\), which is an integer."],
 ["A5", "\\(3 - 2k\\)", allodd, "\\(3 - 2k = 2(1 - k) + 1\\) is always odd, and every odd number \\(n\\) is a value: take \\(k = \\dfrac{3 - n}{2}\\), which is an integer."]
];
poolS: [
 ["S1", "\\(4k + 3\\)", someodd, "\\(4k + 3 = 2(2k + 1) + 1\\) is always odd, but its values are \\(\\ldots, -5, -1, 3, 7, 11, \\ldots\\): 1 is missing, because \\(4k + 3 = 1\\) gives \\(k = -\\dfrac12\\), which is not an integer."],
 ["S2", "\\(6k + 1\\)", someodd, "\\(6k + 1 = 2(3k) + 1\\) is always odd, but its values are \\(\\ldots, -5, 1, 7, 13, \\ldots\\): 3 and 5 are missing."],
 ["S3", "\\(6k + 5\\)", someodd, "\\(6k + 5 = 2(3k + 2) + 1\\) is always odd, but its values are \\(\\ldots, -7, -1, 5, 11, \\ldots\\): 1 and 3 are missing."],
 ["S4", "\\(2k^2 + 1\\)", someodd, "\\(2k^2 + 1\\) is always odd, but its values are \\(1, 3, 9, 19, 33, \\ldots\\): 5 and 7 are missing."],
 ["S5", "\\(k^2 + k + 1\\)", someodd, "\\(k^2 + k = k(k + 1)\\) is a product of two consecutive integers, so it is even and \\(k^2 + k + 1\\) is always odd. But its values are \\(1, 3, 7, 13, 21, \\ldots\\): 5 is missing."]
];
poolN: [
 ["N1", "\\(k + 1\\)", notodd, "When \\(k = 1\\), \\(k + 1 = 2\\), which is even."],
 ["N2", "\\(3k + 1\\)", notodd, "When \\(k = 1\\), \\(3k + 1 = 4\\), which is even."],
 ["N3", "\\(k^2 + 1\\)", notodd, "When \\(k = 1\\), \\(k^2 + 1 = 2\\), which is even."],
 ["N4", "\\(2k + 2\\)", notodd, "\\(2k + 2 = 2(k + 1)\\) is even for every integer \\(k\\), so it is never odd."],
 ["N5", "\\(3k + 2\\)", notodd, "When \\(k = 0\\), \\(3k + 2 = 2\\), which is even."]
];
/* 4k + 1 is not in the pool: the figure shows it. One row from each pool, one more from the rest. */
rA: rand(poolA);
rS: rand(poolS);
rN: rand(poolN);
poolleft: sublist(append(poolA, poolS, poolN), lambda([rw], not(member(rw, [rA, rS, rN]))));
rX: rand(poolleft);
qrows: random_permutation([rA, rS, rN, rX]);
diagof(c) := if c = allodd then someodd else allodd;
otherof(c) := if c = notodd then someodd else notodd;
/* Wrong-answer feedback is a prompt only: the row's explanation names the right category, so it is kept for the correct branch and the worked solution. */
leaddiag(c) := if c = allodd then "The option you chose means that some odd number is never a value. Test it: choose an odd number \\(n\\), set the expression equal to \\(n\\) and solve for \\(k\\). Is \\(k\\) always an integer?" else if c = someodd then "The option you chose means that each odd number is a value for some integer \\(k\\). Test it on small odd numbers such as 1, 3, 5 and 7: set the expression equal to each one and solve for \\(k\\)." else "Before asking which odd numbers appear, check that every value is odd. Try a few values of \\(k\\), such as 0, 1 and 2.";
leadother(c) := if c = notodd then "The option you chose still needs every value to be odd. Check that first: try a few values of \\(k\\), such as 0, 1 and 2." else "Every value of this expression is odd: try writing it as \\(2 \\times (\\text{an integer}) + 1\\). Now decide whether every odd number is a value.";
labsent(c) := if c = allodd then "This gives every odd number." else if c = someodd then "This gives only some odd numbers." else "This is not always odd.";
opts(c) := [[allodd, is(c = allodd), "every odd number"], [someodd, is(c = someodd), "only some odd numbers"], [notodd, is(c = notodd), "not always odd"]];
tex1: qrows[1][2]; cor1: qrows[1][3]; expl1: qrows[1][4];
tex2: qrows[2][2]; cor2: qrows[2][3]; expl2: qrows[2][4];
tex3: qrows[3][2]; cor3: qrows[3][3]; expl3: qrows[3][4];
tex4: qrows[4][2]; cor4: qrows[4][3]; expl4: qrows[4][4];
ta1: opts(cor1); ta2: opts(cor2); ta3: opts(cor3); ta4: opts(cor4);
diag1: diagof(cor1); diag2: diagof(cor2); diag3: diagof(cor3); diag4: diagof(cor4);
other1: otherof(cor1); other2: otherof(cor2); other3: otherof(cor3); other4: otherof(cor4);
fbdiag1: leaddiag(cor1); fbother1: leadother(cor1);
fbdiag2: leaddiag(cor2); fbother2: leadother(cor2);
fbdiag3: leaddiag(cor3); fbother3: leadother(cor3);
fbdiag4: leaddiag(cor4); fbother4: leadother(cor4);
s_assert(is(length(unique([diag1, cor1, other1])) = 3 and length(unique([diag2, cor2, other2])) = 3 and length(unique([diag3, cor3, other3])) = 3 and length(unique([diag4, cor4, other4])) = 3), true);
